function mergeSelectedRoles() {
    try {
        let selectedRoles = getSelectedRoles();
        if (selectedRoles.length < 2) {
            java.longToast("❌至少选择2个角色才能合并");
            return;
        }
        selectedRoles.sort(function(a, b) {
            return b.saveTime - a.saveTime;
        });
        let latestRole = selectedRoles[0];
        let nameSet = {};
        let allNames = [];
        for (var i=0; i<selectedRoles.length; i++) {
            let name = selectedRoles[i].name.trim();
            if (!nameSet[name]) {
                nameSet[name] = true;
                allNames.push(name);
            }
        }
        allNames = allNames.join("|");
        let roleArr = readBookCharacters();
        let selectedNames = [];
        for (var i=0; i<selectedRoles.length; i++) {
            selectedNames.push(selectedRoles[i].name);
        }
        let newRoleArr = [];
        for (var i=0; i<roleArr.length; i++) {
            let isSelected = false;
            for (var j=0; j<selectedNames.length; j++) {
                if (roleArr[i].name === selectedNames[j]) {
                    isSelected = true;
                    break;
                }
            }
            if (!isSelected) {
                newRoleArr.push(roleArr[i]);
            }
        }
        let mergedRole = {name: allNames, genderAge: latestRole.genderAge, voiceNum: latestRole.voiceNum, saveTime: new Date().getTime()};
        newRoleArr.unshift(mergedRole);
        saveBookCharacters(newRoleArr);
        deleteSelectedRoleCaches();
        java.longToast("✅合并成功！\n合并角色数：" + selectedRoles.length + "\n合并后名字：" + allNames);
        java.log("✅合并角色：" + JSON.stringify(mergedRole));
    } catch (e) {
        java.longToast("⚠️合并失败：" + e.message);
        java.log("合并异常：" + e.message);
    }
}
