            "你是喜马拉雅听书软件中智能朗读功能的人声分配AI，任务是精准判断且只判断当前小说手稿中「标记重点对话」的说话人。\n\n**【核心原则 - 最高优先级】**\n1. 严禁将对话引号**内部**提及的人名当作说话人，引号内名字是「说话者谈论的其他人」；\n2. 示例：`张伟说：“别提了，都是为了王明那个项目。”` 中，说话人是**张伟**，绝非王明。\n\n**标记的重点对话是“" + coreDialogue + "”请结合上下文分析出说出这句话的角色名字\n**【输出要求】**\n根据你的分析，返回以下格式的JSON。如果无法确定说话人姓名，就用前后对这个人的描述作为名字，如果连描述也没有，就根据性别年龄填写“群众男青年”、“群众男中年”、“群众男老年”、“群众男少年”、“群众少女”、“群众淑女”、“群众熟女”、“群众老妇”、“群众幼女”其中的一个。\n{\n\"" + characterId + "\": {\n\"name\": \"分析出的说话人姓名\",\n\"gender\": \"性别（男/女）\",\n\"age\": \"年龄分类（女性：幼女/少女/淑女/熟女/老妇）；（男性：少年/青年/中年/老年）\"\n}\n}\n\n";
            var requestBody = JSON.stringify({
                model: GLM_MODEL,
                messages: [
                    { role: 'system', content: prompt },
                    { role: 'user', content: fullContent }
                ],
                temperature: 0.1,
                top_p: 0.5,
                max_tokens: 100
            });
            var response = org.jsoup.Jsoup.connect(GLM_API_URL).method(org.jsoup.Connection.Method.POST).header("Authorization","Bearer " + getCurrentApiKey()).header("Content-Type","application/json").requestBody(requestBody).timeout(15000).ignoreContentType(true).execute();
            if (response.statusCode() == 200) {
                var resJson = JSON.parse(response.body());
                var apiResult = "";
                if (resJson.choices && resJson.choices[0] && resJson.choices[0].message && resJson.choices[0].message.content) {
                    apiResult = resJson.choices[0].message.content.trim();
                }
                if (apiResult) {
                    var resultJson = null;
                    try {
                        resultJson = JSON.parse(apiResult);
                    } catch (e) {
                        resultJson = null;
                    }
                    if (resultJson && resultJson[characterId]) {
                        var speakerInfo = resultJson[characterId];
                        var name = cleanCharacterName(speakerInfo.name || "");
                        var gender = speakerInfo.gender || "女";
                        var age = speakerInfo.age || "淑女";
                        var genderAgeKey = gender + "-" + age;
                        var newGenderAge = genderAgeMap[genderAgeKey] || "女淑女";
                        if (name && genderAgeToVoiceNums[newGenderAge]) {
                            isRecognizeSuccess = true;
                            var charArr = readCharacters();
                            var cacheChar = null;
                            var aliasMatchChar = null;
                            var needMergeAlias = false;
                            for (var i=0; i<charArr.length; i++) {
                                if (isNameMatch(charArr[i].name, name)) {
                                    cacheChar = charArr[i];
                                    break;
                                }
                            }
                            if (!cacheChar && name !== "未知") {
                                var sameGenderChars = [];
                                for (var i=0; i<charArr.length; i++) {
                                    if (charArr[i].genderAge === newGenderAge) {
                                        sameGenderChars.push(charArr[i]);
                                    }
                                }
                                if (sameGenderChars.length > 0) {
                                    for (var i=0; i<sameGenderChars.length; i++) {
                                        var currRole = sameGenderChars[i];
                                        var aliasCheck = checkIsAlias(name, currRole.name, chapterFullContent);
                                        if (aliasCheck.isAlias === true) {
                                            aliasMatchChar = currRole;
                                            needMergeAlias = true;
                                            break;
                                        }
                                    }
                                }
                            }
                            if (cacheChar) {
                                finalGenderAge = cacheChar.genderAge;
                                targetNum = isValidVoiceNum(cacheChar.voiceNum) ? cacheChar.voiceNum : "00";
                                saveCharacter(cacheChar.name, finalGenderAge, targetNum);
                            } else if (aliasMatchChar && needMergeAlias) {
                                finalGenderAge = aliasMatchChar.genderAge;
                                targetNum = isValidVoiceNum(aliasMatchChar.voiceNum) ? aliasMatchChar.voiceNum : "00";
                                var mergedName = mergeAlias(aliasMatchChar.name, name);
                                saveCharacter(mergedName, finalGenderAge, targetNum);
                            } else {
                                finalGenderAge = newGenderAge;
                                targetNum = getTargetVoiceNum(finalGenderAge);
                                saveCharacter(name, finalGenderAge, targetNum);
                            }
                            characterName = name;
                        }
                    }
                }
            }
        }
        catch (e) {
            isGLMFail = true;
            var qIdx = cache.get("quoteVoiceIdx") || 1;
            qIdx = parseInt(qIdx);
            targetNum = isValidVoiceNum(qIdx) ? qIdx : DEFAULT_VOICE_IDX;
            isRecognizeSuccess = true;
        }
    }

    if (!isRecognizeSuccess) {
        finalGenderAge = "女淑女";
        targetNum = getTargetVoiceNum(finalGenderAge);
    }

    finalText = currentParagraph.replace(/“/g, "“" + targetNum);
    finalText = finalText.replace(/<<[^<>]*>>/g, "").trim();
}

// ====================== TTS合成逻辑（✅ 核心修改：旁白强制禁止知更鸟）======================
ttsText = finalText;
saveCurrentToHistory(currentParagraph);

currentApiIdx = cache.get("NextTTS") || 0;
currentApiIdx = parseInt(currentApiIdx);
currentApiIdx = Math.min(Math.max(currentApiIdx,0), apis.length-1);
cache.put("NextTTS", currentApiIdx);

// ✅【关键修改】旁白发音人（sz）强制过滤知更鸟（52-64），重置为默认23
var sz = source.getLoginHeader();
sz = parseInt(sz);
if (isNaN(sz) || sz < 0 || sz >= data.length || (sz >= ZG_VOICE_MIN && sz <= ZG_VOICE_MAX)) {
    sz = DEFAULT_VOICE_IDX;
    source.putLoginHeader(sz);
}
var targetVoiceId = getVoiceIdSafe(sz);

var quoteIdx = cache.get("quoteVoiceIdx") || 1;
quoteIdx = parseInt(quoteIdx);
if (quoteIdx < 0 || quoteIdx > 64) quoteIdx = 1;

var num = null;
var numMatch = finalText.match(/“(\d{1,2})/);
if (numMatch) {
    num = parseInt(numMatch[1]);
    if (isValidVoiceNum(num)) targetVoiceId = getVoiceIdSafe(num);
    else targetVoiceId = getVoiceIdSafe(quoteIdx);
    ttsText = ttsText.replace(/“\d{1,2}/g, "“");
} else if (finalText.indexOf("“")>-1 || finalText.indexOf("\"")>-1) {
    targetVoiceId = getVoiceIdSafe(quoteIdx);
}
var finalUseNum = num && isValidVoiceNum(num) ? num : sz;
var requestSuccess = false;

// 纳米TTS（无修改）
function nanoTTS(roleId) {
    let getTime = (o) => new Date(Date.now()+o*36e5).toISOString().replace('Z',`+${o.toString().padStart(2,'0')}:00`);
    let time = getTime(8);
    let _e = [
        "Web", time, "1.2", 
        "21329384620368073434705174017567", 
        java.md5Encode(java.getWebViewUA())
    ];
    let et = {
        "User-Agent": java.getWebViewUA(),
        "device-platform": _e[0],
        "timestamp": _e[1],
        "zm-ver": _e[2],
        "access-token": _e[3],
        "zm-token": "",
        "zm-ua": _e[4]
    };
    _e[3] || _e.splice(3,1);
    et["zm-token"] = java.md5Encode(_e.join(""));
    let u = `https://bot.n.cn/api/tts/v1?roleid=${roleId}`;
    let body = `text=${encodeURIComponent(ttsText)}&set_speed=${speakSpeed / 10}&audio_type=mp3&format=stream`;
    return `${u},{"body":"${body}","headers":${JSON.stringify(et)},"method":"POST"}`;
}

// 知更鸟TTS（无修改）
function zgTTS(voiceId) {
    function specialCharReplace(s) {
        return s.replace(/'/g, "&apos;").replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/&/g, '&amp;').replace(/\//g, '').replace(/\\/g, '');
    }
    function generateRandomToken() {
        const chars = '0123456789abcdef';
        let token = '';
        for (let i = 0; i < 32; i++) {
            token += chars[Math.floor(Math.random() * 16)];
        }
        return token;
    }
    let _speakSpeed = typeof speakSpeed === 'number' ? speakSpeed : 10;
    let _voiceId = typeof voiceId === 'string' && voiceId.trim() ? voiceId.trim() : "zhixiaobai";
    let _ttsText = typeof ttsText === 'string' ? ttsText : "音频合成失败，请重试";
    let apiRate = 5;
    let apiPitch = 5, apiVolume = 3, emotion = "nuetral", format = "mp3";
    let processedText = specialCharReplace(_ttsText);

    try {
        let postUrl = "https://user.api.hudunsoft.com/v1/alivoice/texttoaudio";
        let postParams = [
            `text=${encodeURIComponent(processedText)}`,
            `voice=${encodeURIComponent(_voiceId)}`,
            `format=${format}`,
            `speech_rate=${apiRate}`,
            `pitch_rate=${apiPitch}`,
            `volume=${apiVolume}`,
            `emotion=${emotion}`,
            `token=${generateRandomToken()}`
        ].join('&');
        let postHeaders = {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Product': '335',
            'X-Version': '5.7.0.0',
            'User-Agent': java.getWebViewUA()
        };
        let postResp = org.jsoup.Jsoup.connect(postUrl).method(org.jsoup.Connection.Method.POST).headers(postHeaders).requestBody(postParams).timeout(15000).ignoreContentType(true).execute();
        if (postResp.statusCode() !== 200) throw new Error("POST请求失败");
        let respJson = JSON.parse(postResp.body());
        if (respJson.code !== 0) throw new Error("接口错误：" + respJson.msg);
        let audioUrl = respJson.data.url || respJson.data.file_link;
        if (!audioUrl) throw new Error("未解析到音频直链");
        return audioUrl;
    } catch (e) {
        console.log("知更鸟TTS异常：" + e.message);
        return "https://cdn.jsdelivr.net/gh/xxx/empty-audio.mp3";
    }
}

// 链路判断（无修改，旁白已被过滤，不会进入知更鸟链路）
if (finalUseNum >= NANO_VOICE_MIN && finalUseNum <= NANO_VOICE_MAX) {
    requestUrl = nanoTTS(getVoiceIdSafe(finalUseNum));
    requestSuccess = true;
} else if (finalUseNum >= ZG_VOICE_MIN && finalUseNum <= ZG_VOICE_MAX) {
    requestUrl = zgTTS(getVoiceIdSafe(finalUseNum));
    requestSuccess = true;
} else if (!requestSuccess) {
    var retryCount = 0;
    var currentApi = apis[currentApiIdx] || apis[0];
    if (isGLMFail) {
        var priorityVoices = [];
        var qIdx = parseInt(cache.get("quoteVoiceIdx") || 1);
        if (isValidVoiceNum(qIdx)) priorityVoices.push(qIdx);
        priorityVoices.push(DEFAULT_VOICE_IDX);
        priorityVoices.push(parseInt(targetNum));

        while (retryCount < MAX_RETRY && !requestSuccess) {
            for (var i=0; i<priorityVoices.length && !requestSuccess; i++) {
                try {
                    var currVoice = priorityVoices[i];
                    targetVoiceId = getVoiceIdSafe(currVoice);
                    requestUrl = buildMsRequest(currentApi, targetVoiceId);
                    var resp = org.jsoup.Jsoup.connect(requestUrl.split(",")[0]).timeout(15000).ignoreContentType(true).execute();
                    requestSuccess = resp && resp.statusCode() === 200;
                } catch (e) { continue; }
            }
            if (!requestSuccess) {
                switchNextApi();
                currentApi = apis[currentApiIdx];
                retryCount++;
            }
        }
    } else {
        while (retryCount < MAX_RETRY && !requestSuccess) {
            try {
                requestUrl = buildMsRequest(currentApi, targetVoiceId);
                var resp = org.jsoup.Jsoup.connect(requestUrl.split(",")[0]).timeout(15000).ignoreContentType(true).execute();
                requestSuccess = resp && resp.statusCode() === 200;
            } catch (e) { requestSuccess = false; }
            if (!requestSuccess) {
                switchNextApi();
                currentApi = apis[currentApiIdx];
                retryCount++;
            }
        }
    }
}

function buildMsRequest(api, voiceId) {
    var url = api[0] || apis[0][0];
    if (api[3] && api[3] === "POST") {
        var params = JSON.stringify({
            "input":ttsText,"voice":voiceId,"speed":speakSpeed/10,
            "pitch":"0","style":source.getVariable()||"general"
        });
        return url + ",{\"body\":" + params + ",\"method\":\"POST\"}";
    } else {
        var params = "?t=" + encodeURIComponent(ttsText) + "&v=" + voiceId + "&r=" + (speakSpeed-10)*10 + "&p=0&s=" + (source.getVariable()||"") + "&api_key=" + (api[2]||"");
        return url + params;
    }
}

// 兜底逻辑（无修改）
if (!requestSuccess && !(finalUseNum >= NANO_VOICE_MIN && finalUseNum <= NANO_VOICE_MAX) && !(finalUseNum >= ZG_VOICE_MIN && finalUseNum <= ZG_VOICE_MAX)) {
    ttsText = "音频合成失败（已重试"+MAX_RETRY+"次），请稍后再试";
    requestUrl = apis[0][0] + "?t=" + encodeURIComponent(ttsText) + "&v=" + getVoiceIdSafe(DEFAULT_VOICE_IDX);
}

requestUrl;
